const MARK_VIEWBOX = '139 252 584 469';
const MARK_ASPECT = 584 / 469;

const WORDMARK_FONT = 'var(--font-space-grotesk), system-ui, sans-serif';

/** Crema del logo (#f8f5f0) en oscuro; índigo profundo en claro. */
const BRAND_COLOR = 'text-[#1e1b4b] dark:text-[#f8f5f0]';

/** Solo el ícono. `height` es la altura en píxeles; el ancho se calcula solo. */
export function KeeplerMark({
  height = 28,
  className = '',
}: {
  height?: number;
  className?: string;
}) {
  return (
    <svg
      viewBox={MARK_VIEWBOX}
      width={Math.round(height * MARK_ASPECT)}
      height={height}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      className={`flex-shrink-0 ${BRAND_COLOR} ${className}`}
    >
      {KEEPLER_MARK_PATHS.map((d, i) => (
        <path key={i} d={d} />
      ))}
    </svg>
  );
}

/** Solo la palabra "Keepler". `className` controla el tamaño de letra. */
export function KeeplerWordmark({ className = 'text-[20px]' }: { className?: string }) {
  return (
    <span
      className={`font-bold leading-none tracking-tight ${BRAND_COLOR} ${className}`}
      style={{ fontFamily: WORDMARK_FONT }}
    >
      Keepler
    </span>
  );
}

/** Ícono + logotipo. `stacked` los pone uno encima del otro (login). */
export function KeeplerLogo({
  size = 'sm',
  stacked = false,
  className = '',
}: {
  size?: 'sm' | 'md' | 'lg';
  stacked?: boolean;
  className?: string;
}) {
  const config = {
    sm: { icon: 26, text: 'text-[21px]' },
    md: { icon: 44, text: 'text-[26px]' },
    lg: { icon: 84, text: 'text-[36px]' },
  }[size];

  return (
    <span
      className={`inline-flex ${stacked ? 'flex-col items-center gap-4' : 'items-center gap-2.5'} ${className}`}
    >
      <KeeplerMark height={config.icon} />
      <KeeplerWordmark className={config.text} />
    </span>
  );
}
